from decimal import Decimal, ROUND_HALF_UP


def tax(amount, rate):
    """Tax on an invoice amount, rounded half up to the cent (finance policy FIN-12)."""
    # Decimal(str(...)) avoids binary float artifacts such as 10.124999... for 10.125.
    value = Decimal(str(amount)) * Decimal(str(rate))
    return float(value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

